import React, { useState, useEffect, useMemo } from "react";
import { studentsAPI, attendanceAPI } from "./api_service";

// Configuration des couleurs pour une UI moderne
const COLORS = {
  primary: "#4F46E5",
  primaryLight: "#EEF2FF",
  success: "#10B981",
  successLight: "#DCFCE7",
  danger: "#EF4444",
  dangerLight: "#FEE2E2",
  warning: "#F59E0B",
  warningLight: "#FEF3C7",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0",
  background: "#F8FAFC",
  surface: "#FFFFFF"
};

const Dashboard = () => {
  // --- ÉTATS ---
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(true); // Activé par défaut
  const [lastUpdated, setLastUpdated] = useState(new Date());

  // --- CHARGEMENT DES DONNÉES ---
  const loadData = async () => {
    try {
      // On ne montre le loader principal que lors du tout premier chargement
      if (attendanceLog.length === 0) setLoading(true);

      // Exécution parallèle des 4 requêtes nécessaires
      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),      // /students/stats/
        attendanceAPI.getStats(),    // /attendance/stats/
        attendanceAPI.getTodayLog(), // /attendance/
        attendanceAPI.getStatus()     // /attendance/status/
      ]);

      // Vérification si toutes les requêtes ont réussi
      if (!studentStatsRes.success || !attendanceStatsRes.success) {
        throw new Error("Certaines API n'ont pas répondu correctement.");
      }

      const sData = studentStatsRes.data || {};
      const aSummary = attendanceStatsRes.data || {};

      // Mise à jour des compteurs globaux
      setStats({
        active_students: Number(sData.active_students) || 0,
        present_today: Number(sData.total_attendance) || 0,
        absent_today: Math.max(0, (Number(sData.active_students) || 0) - (Number(sData.total_attendance) || 0)),
        summary: {
          unique_students: Number(aSummary.unique_students) || 0,
          total_records: Number(aSummary.total_records) || 0,
          avg_confidence: Number(aSummary.avg_confidence) || 0,
          max_confidence: Number(aSummary.max_confidence) || 0,
          min_confidence: Number(aSummary.min_confidence) || 0
        }
      });

      // Journal des entrées : extraction sécurisée de 'records'
      const logs = logRes.data?.records || logRes.data || [];
      setAttendanceLog(Array.isArray(logs) ? logs : []);

      // Liste de présence : extraction sécurisée de 'students'
      const students = statusRes.data?.students || statusRes.data || [];
      setStatusList(Array.isArray(students) ? students : []);

      setLastUpdated(new Date());
      setError(null);

    } catch (err) {
      console.error("❌ Erreur Dashboard API:", err);
      setError("Erreur de liaison avec le serveur. Vérifiez que le backend est lancé.");
    } finally {
      setLoading(false);
    }
  };

  // --- EFFETS ---
  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    let timer;
    if (autoRefresh) {
      timer = setInterval(loadData, 10000); // Refresh toutes les 10 secondes
    }
    return () => clearInterval(timer);
  }, [autoRefresh]);

  // --- CALCULS (Memoized) ---
  const cards = useMemo(() => {
    const total = stats.active_students || 0;
    const present = stats.present_today || 0;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      { id: 'total', label: "Étudiants Inscrits", value: total, icon: "👥", color: COLORS.primary, bgColor: COLORS.primaryLight },
      { id: 'present', label: "Présents (Aujourd'hui)", value: present, icon: "✅", color: COLORS.success, bgColor: COLORS.successLight },
      { id: 'absent', label: "Absents", value: stats.absent_today, icon: "❌", color: COLORS.danger, bgColor: COLORS.dangerLight },
      { id: 'rate', label: "Taux de Présence", value: `${rate}%`, icon: "📈", color: "#8B5CF6", bgColor: "#F5F3FF" }
    ];
  }, [stats]);

  // --- RENDU : LOADING ---
  if (loading) {
    return (
      <div style={styles.loaderContainer}>
        <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
        <div style={styles.spinner}></div>
        <p style={styles.loaderText}>Chargement des données du backend...</p>
      </div>
    );
  }

  // --- RENDU : DASHBOARD ---
  return (
    <div style={styles.pageWrapper}>
      <header style={styles.header}>
        <div>
          <h1 style={styles.title}>Dashboard de Présence</h1>
          <p style={styles.subtitle}>Dernière mise à jour : {lastUpdated.toLocaleTimeString()}</p>
        </div>

        <div style={styles.actions}>
          <label style={styles.switchContainer}>
            <input 
              type="checkbox" 
              checked={autoRefresh} 
              onChange={() => setAutoRefresh(!autoRefresh)}
              style={styles.switchInput}
            />
            <span style={styles.switchLabel}>Auto-Refresh (10s)</span>
          </label>
          <button onClick={loadData} style={styles.refreshBtn}>🔄 Actualiser</button>
        </div>
      </header>

      {error && <div style={styles.errorAlert}>{error}</div>}

      {/* Grille des Cartes de Stats */}
      <div style={styles.statsGrid}>
        {cards.map((card) => (
          <div key={card.id} style={styles.statCard}>
            <div style={{...styles.iconWrapper, backgroundColor: card.bgColor, color: card.color}}>{card.icon}</div>
            <div style={styles.statInfo}>
              <span style={styles.statLabel}>{card.label}</span>
              <span style={styles.statValue}>{card.value}</span>
            </div>
          </div>
        ))}
      </div>

      <div style={styles.mainLayout}>
        {/* Section Gauche : Journal des Scans */}
        <section style={styles.sectionCard}>
          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>Journal des Entrées</h3>
            <span style={styles.badgeCount}>{attendanceLog.length} aujourd'hui</span>
          </div>
          <div style={styles.tableWrapper}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Étudiant</th>
                  <th style={styles.th}>Heure</th>
                  <th style={styles.th}>Confiance IA</th>
                </tr>
              </thead>
              <tbody>
                {attendanceLog.map((row, i) => (
                  <tr key={i} style={styles.tr}>
                    <td style={styles.tdBold}>{row.student}</td>
                    <td style={styles.td}>{row.timestamp}</td>
                    <td style={styles.td}>
                      <span style={{
                        ...styles.confBadge,
                        color: row.confidence > 0.8 ? COLORS.success : COLORS.warning,
                        backgroundColor: row.confidence > 0.8 ? COLORS.successLight : COLORS.warningLight
                      }}>
                        {(row.confidence * 100).toFixed(1)}%
                      </span>
                    </td>
                  </tr>
                ))}
                {attendanceLog.length === 0 && (
                  <tr><td colSpan="3" style={styles.empty}>Aucun scan détecté.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        {/* Section Droite : Statut de la classe */}
        <aside style={styles.sectionCard}>
          <h3 style={styles.sectionTitle}>Statut de la Classe</h3>
          <div style={styles.statusList}>
            {statusList.map((st, i) => (
              <div key={i} style={styles.statusItem}>
                <div style={styles.statusInfo}>
                  <p style={styles.studentName}>{st.name}</p>
                  <p style={styles.studentEmail}>{st.email}</p>
                </div>
                <div style={{
                  ...styles.statusIndicator,
                  backgroundColor: st.present ? COLORS.success : COLORS.danger
                }}>
                  {st.present ? "Présent" : "Absent"}
                </div>
              </div>
            ))}
          </div>
        </aside>
      </div>
    </div>
  );
};

